     1→"use client";
     2→
     3→import {
     4→	closestCenter,
     5→	DndContext,
     6→	type DragEndEvent,
     7→	type DragOverEvent,
     8→	DragOverlay,
     9→	type DragStartEvent,
    10→	KeyboardSensor,
    11→	PointerSensor,
    12→	pointerWithin,
    13→	useSensor,
    14→	useSensors,
    15→} from "@dnd-kit/core";
    16→import { arrayMove, sortableKeyboardCoordinates } from "@dnd-kit/sortable";
    17→import type { Question, Survey } from "@orksys-survey/db";
    18→import { useMutation, useQueryClient } from "@tanstack/react-query";
    19→import {
    20→	ClipboardList,
    21→	GripVertical,
    22→	PanelLeftClose,
    23→	PanelRightClose,
    24→} from "lucide-react";
    25→import { createContext, useContext, useEffect, useState } from "react";
    26→import { toast } from "sonner";
    27→
    28→import { Button } from "@/components/ui/button";
    29→import { Card, CardContent } from "@/components/ui/card";
    30→import { Sheet, SheetContent } from "@/components/ui/sheet";
    31→import { useMediaQuery } from "@/hooks/use-media-query";
    32→import { cn } from "@/lib/utils";
    33→import { orpc } from "@/utils/orpc";
    34→import { BuilderCanvas } from "./builder-canvas";
    35→import { BuilderHeader } from "./builder-header";
    36→import { PropertiesPanel } from "./properties-panel";
    37→import { QuestionPalette } from "./question-palette";
    38→
    39→// Question type configs for drag overlay
    40→const questionTypeIcons: Record<string, React.ElementType> = {
    41→	text: ClipboardList,
    42→	textarea: ClipboardList,
    43→	multiple_choice: ClipboardList,
    44→	checkbox: ClipboardList,
    45→	dropdown: ClipboardList,
    46→	rating: ClipboardList,
    47→	nps: ClipboardList,
    48→	linear_scale: ClipboardList,
    49→	date: ClipboardList,
    50→	email: ClipboardList,
    51→	phone: ClipboardList,
    52→	file_upload: ClipboardList,
    53→};
    54→
    55→const questionTypeLabels: Record<string, string> = {
    56→	text: "Short Text",
    57→	textarea: "Long Text",
    58→	multiple_choice: "Multiple Choice",
    59→	checkbox: "Checkboxes",
    60→	dropdown: "Dropdown",
    61→	rating: "Rating",
    62→	nps: "NPS",
    63→	linear_scale: "Linear Scale",
    64→	date: "Date",
    65→	email: "Email",
    66→	phone: "Phone",
    67→	file_upload: "File Upload",
    68→};
    69→
    70→// Builder context for sharing state across components
    71→interface SurveyBuilderContextValue {
    72→	survey: Survey;
    73→	questions: Question[];
    74→	selectedQuestionId: string | null;
    75→	setSelectedQuestionId: (id: string | null) => void;
    76→	activeTab: "build" | "preview";
    77→	setActiveTab: (tab: "build" | "preview") => void;
    78→	onQuestionsChange: (questions: Question[]) => void;
    79→	paletteOpen: boolean;
    80→	setPaletteOpen: (open: boolean) => void;
    81→	propertiesOpen: boolean;
    82→	setPropertiesOpen: (open: boolean) => void;
    83→}
    84→
    85→const SurveyBuilderContext = createContext<SurveyBuilderContextValue | null>(
    86→	null,
    87→);
    88→
    89→export function useSurveyBuilder() {
    90→	const context = useContext(SurveyBuilderContext);
    91→	if (!context) {
    92→		throw new Error(
    93→			"useSurveyBuilder must be used within a SurveyBuilder component",
    94→		);
    95→	}
    96→	return context;
    97→}
    98→
    99→// Drag item types
   100→interface PaletteDragItem {
   101→	type: "palette";
   102→	questionType: Question["type"];
   103→}
   104→
   105→interface QuestionDragItem {
   106→	type: "question";
   107→	id: string;
   108→}
   109→
   110→type DragItem = PaletteDragItem | QuestionDragItem;
   111→
   112→interface SurveyBuilderProps {
   113→	survey: Survey;
   114→	questions: Question[];
   115→	className?: string;
   116→}
   117→
   118→export function SurveyBuilder({
   119→	survey,
   120→	questions: initialQuestions,
   121→	className,
   122→}: SurveyBuilderProps) {
   123→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
   124→		null,
   125→	);
   126→	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
   127→	const [questions, setQuestions] = useState(initialQuestions);
   128→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
   129→	const [paletteOpen, setPaletteOpen] = useState(false);
   130→	const [propertiesOpen, setPropertiesOpen] = useState(false);
   131→
   132→	// Responsive breakpoints
   133→	const isDesktop = useMediaQuery("(min-width: 1024px)");
   134→
   135→	const queryClient = useQueryClient();
   136→
   137→	// Sync state when initialQuestions changes
   138→	useEffect(() => {
   139→		setQuestions(initialQuestions);
   140→	}, [initialQuestions]);
   141→
   142→	// Create question mutation (for palette drops)
   143→	const createMutation = useMutation(
   144→		orpc.question.create.mutationOptions({
   145→			onSuccess: (newQuestion) => {
   146→				setQuestions((prev) => [...prev, newQuestion]);
   147→				setSelectedQuestionId(newQuestion.id);
   148→				queryClient.invalidateQueries({ queryKey: ["question"] });
   149→				toast.success("Question added");
   150→			},
   151→			onError: (error) => {
   152→				toast.error(error.message || "Failed to create question");
   153→			},
   154→		}),
   155→	);
   156→
   157→	// Reorder mutation
   158→	const reorderMutation = useMutation(
   159→		orpc.question.reorder.mutationOptions({
   160→			onSuccess: () => {
   161→				queryClient.invalidateQueries({ queryKey: ["question"] });
   162→			},
   163→			onError: (error) => {
   164→				toast.error(error.message || "Failed to reorder questions");
   165→			},
   166→		}),
   167→	);
   168→
   169→	// DnD sensors
   170→	const sensors = useSensors(
   171→		useSensor(PointerSensor, {
   172→			activationConstraint: {
   173→				distance: 5,
   174→			},
   175→		}),
   176→		useSensor(KeyboardSensor, {
   177→			coordinateGetter: sortableKeyboardCoordinates,
   178→		}),
   179→	);
   180→
   181→	const handleDragStart = (event: DragStartEvent) => {
   182→		const { active } = event;
   183→		const data = active.data.current;
   184→
   185→		if (data?.questionType) {
   186→			// Dragging from palette
   187→			setActiveDragItem({
   188→				type: "palette",
   189→				questionType: data.questionType as Question["type"],
   190→			});
   191→		} else {
   192→			// Dragging existing question
   193→			setActiveDragItem({
   194→				type: "question",
   195→				id: active.id as string,
   196→			});
   197→		}
   198→	};
   199→
   200→	const handleDragOver = (_event: DragOverEvent) => {
   201→		// Just update visual state if needed, don't create questions
   202→		// Question creation happens in handleDragEnd
   203→	};
   204→
   205→	const handleDragEnd = (event: DragEndEvent) => {
   206→		const { active, over } = event;
   207→		setActiveDragItem(null);
   208→
   209→		if (!over) return;
   210→
   211→		// Handle palette drop on canvas (create new question)
   212→		if (active.data.current?.questionType && over.id === "canvas") {
   213→			const questionType = active.data.current.questionType as Question["type"];
   214→			createMutation.mutate({
   215→				surveyId: survey.id,
   216→				type: questionType,
   217→				title: `New ${questionTypeLabels[questionType] || questionType}`,
   218→				order: questions.length,
   219→			});
   220→			return;
   221→		}
   222→
   223→		// Handle reordering
   224→		if (active.id !== over.id && over.id !== "canvas") {
   225→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   226→			const newIndex = questions.findIndex((q) => q.id === over.id);
   227→
   228→			if (oldIndex !== -1 && newIndex !== -1) {
   229→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   230→					(q, index) => ({
   231→						...q,
   232→						order: index,
   233→					}),
   234→				);
   235→
   236→				setQuestions(newQuestions);
   237→
   238→				reorderMutation.mutate({
   239→					questions: newQuestions.map((q) => ({
   240→						id: q.id,
   241→						order: q.order,
   242→					})),
   243→				});
   244→			}
   245→		}
   246→	};
   247→
   248→	const contextValue: SurveyBuilderContextValue = {
   249→		survey,
   250→		questions,
   251→		selectedQuestionId,
   252→		setSelectedQuestionId,
   253→		activeTab,
   254→		setActiveTab,
   255→		onQuestionsChange: setQuestions,
   256→		paletteOpen,
   257→		setPaletteOpen,
   258→		propertiesOpen,
   259→		setPropertiesOpen,
   260→	};
   261→
   262→	const safeQuestions = questions || [];
   263→
   264→	// Render drag overlay
   265→	const renderDragOverlay = () => {
   266→		if (!activeDragItem) return null;
   267→
   268→		if (activeDragItem.type === "palette") {
   269→			const Icon =
   270→				questionTypeIcons[activeDragItem.questionType] || ClipboardList;
   271→			return (
   272→				<Card className="shadow-lg">
   273→					<CardContent className="flex items-center gap-3 p-4">
   274→						<GripVertical className="h-4 w-4 text-neutral-400" />
   275→						<Icon className="h-5 w-5 text-violet-500" />
   276→						<span className="font-medium">
   277→							{questionTypeLabels[activeDragItem.questionType] ||
   278→								activeDragItem.questionType}
   279→						</span>
   280→					</CardContent>
   281→				</Card>
   282→			);
   283→		}
   284→
   285→		// Dragging existing question
   286→		const activeQuestion = safeQuestions.find(
   287→			(q) => q.id === activeDragItem.id,
   288→		);
   289→		if (activeQuestion) {
   290→			const Icon = questionTypeIcons[activeQuestion.type] || ClipboardList;
   291→			return (
   292→				<Card className="shadow-lg">
   293→					<CardContent className="flex items-center gap-3 p-4">
   294→						<GripVertical className="h-4 w-4 text-neutral-400" />
   295→						<Icon className="h-5 w-5 text-violet-500" />
   296→						<span className="font-medium">{activeQuestion.title}</span>
   297→					</CardContent>
   298→				</Card>
   299→			);
   300→		}
   301→
   302→		return null;
   303→	};
   304→
   305→	return (
   306→		<SurveyBuilderContext.Provider value={contextValue}>
   307→			<DndContext
   308→				sensors={sensors}
   309→				collisionDetection={pointerWithin}
   310→				onDragStart={handleDragStart}
   311→				onDragEnd={handleDragEnd}
   312→			>
   313→				<div className={cn("flex h-full flex-col", className)}>
   314→					<BuilderHeader
   315→						leftActions={
   316→							!isDesktop &&
   317→							activeTab === "build" && (
   318→								<div className="flex items-center gap-1">
   319→									<Button
   320→										variant="ghost"
   321→										size="icon"
   322→										onClick={() => setPaletteOpen(!paletteOpen)}
   323→									>
   324→										<PanelLeftClose className="h-4 w-4" />
   325→									</Button>
   326→								</div>
   327→							)
   328→						}
   329→						rightActions={
   330→							!isDesktop &&
   331→							activeTab === "build" && (
   332→								<div className="flex items-center gap-1">
   333→									<Button
   334→										variant="ghost"
   335→										size="icon"
   336→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   337→									>
