   358→									>
   359→										<PanelLeftClose className="h-4 w-4" />
   360→									</Button>
   361→								</div>
   362→							)
   363→						}
   364→						rightActions={
   365→							!isDesktop &&
   366→							activeTab === "build" && (
   367→								<div className="flex items-center gap-1">
   368→									<Button
   369→										variant="ghost"
   370→										size="icon"
   371→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   372→									>
   373→										<PanelRightClose className="h-4 w-4" />
   374→									</Button>
   375→								</div>
   376→							)
   377→						}
   378→					/>
   379→					<div className="flex flex-1 overflow-hidden">
   380→						{/* Left Palette - Responsive */}
   381→						{activeTab === "build" && (
