   392→									</Sheet>
   393→								)}
   394→							</>
   395→						)}
   396→
   397→						{/* Canvas */}
   398→						<BuilderCanvas
   399→							questions={questions}
   400→							onQuestionsChange={setQuestions}
   401→							activeDragItem={activeDragItem}
