"use client";

import {
	type CollisionDetection,
	closestCenter,
	DndContext,
	type DragEndEvent,
	type DragOverEvent,
	DragOverlay,
	type DragStartEvent,
	defaultDropAnimation,
	KeyboardSensor,
	PointerSensor,
	pointerWithin,
	useSensor,
	useSensors,
} from "@dnd-kit/core";
import { arrayMove, sortableKeyboardCoordinates } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { Question, Survey } from "@orksys-survey/db";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import {
	ClipboardList,
	GripVertical,
	PanelLeftClose,
	PanelRightClose,
} from "lucide-react";
import { createContext, useContext, useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Sheet, SheetContent } from "@/components/ui/sheet";
import { useMediaQuery } from "@/hooks/use-media-query";
import { cn } from "@/lib/utils";
import { orpc } from "@/utils/orpc";
import { BuilderCanvas } from "./builder-canvas";
import { BuilderHeader } from "./builder-header";
import { PropertiesPanel } from "./properties-panel";
import { QuestionPalette } from "./question-palette";

// Question type configs for drag overlay
const questionTypeIcons: Record<string, React.ElementType> = {
	text: ClipboardList,
	textarea: ClipboardList,
	multiple_choice: ClipboardList,
	checkbox: ClipboardList,
	dropdown: ClipboardList,
	rating: ClipboardList,
	nps: ClipboardList,
	linear_scale: ClipboardList,
	date: ClipboardList,
	email: ClipboardList,
	phone: ClipboardList,
	file_upload: ClipboardList,
};

const questionTypeLabels: Record<string, string> = {
	text: "Short Text",
	textarea: "Long Text",
	multiple_choice: "Multiple Choice",
	checkbox: "Checkboxes",
	dropdown: "Dropdown",
	rating: "Rating",
	nps: "NPS",
	linear_scale: "Linear Scale",
	date: "Date",
	email: "Email",
	phone: "Phone",
	file_upload: "File Upload",
};

// Builder context for sharing state across components
interface SurveyBuilderContextValue {
	survey: Survey;
	questions: Question[];
	selectedQuestionId: string | null;
	setSelectedQuestionId: (id: string | null) => void;
	activeTab: "build" | "preview";
	setActiveTab: (tab: "build" | "preview") => void;
	onQuestionsChange: (questions: Question[]) => void;
	paletteOpen: boolean;
	setPaletteOpen: (open: boolean) => void;
	propertiesOpen: boolean;
	setPropertiesOpen: (open: boolean) => void;
}

const SurveyBuilderContext = createContext<SurveyBuilderContextValue | null>(
	null,
);

export function useSurveyBuilder() {
	const context = useContext(SurveyBuilderContext);
	if (!context) {
		throw new Error(
			"useSurveyBuilder must be used within a SurveyBuilder component",
		);
	}
	return context;
}

// Drag item types
interface PaletteDragItem {
	type: "palette";
	questionType: Question["type"];
}

interface QuestionDragItem {
	type: "question";
	id: string;
}

type DragItem = PaletteDragItem | QuestionDragItem;

interface SurveyBuilderProps {
	survey: Survey;
	questions: Question[];
	className?: string;
}

export function SurveyBuilder({
	survey,
	questions: initialQuestions,
	className,
}: SurveyBuilderProps) {
	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
		null,
	);
	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
	const [questions, setQuestions] = useState(initialQuestions);
	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
	const [paletteOpen, setPaletteOpen] = useState(false);
	const [propertiesOpen, setPropertiesOpen] = useState(false);

	// Responsive breakpoints
	const isDesktop = useMediaQuery("(min-width: 1024px)");

	const queryClient = useQueryClient();

	// Sync state when initialQuestions changes
	useEffect(() => {
		setQuestions(initialQuestions);
	}, [initialQuestions]);

	// Create question mutation (for palette drops)
	const createMutation = useMutation(
		orpc.question.create.mutationOptions({
			onSuccess: (newQuestion) => {
				setQuestions((prev) => [...prev, newQuestion]);
				setSelectedQuestionId(newQuestion.id);
				queryClient.invalidateQueries({ queryKey: ["question"] });
				toast.success("Question added");
			},
			onError: (error) => {
				toast.error(error.message || "Failed to create question");
			},
		}),
	);

	// Reorder mutation
	const reorderMutation = useMutation(
		orpc.question.reorder.mutationOptions({
			onSuccess: () => {
				queryClient.invalidateQueries({ queryKey: ["question"] });
			},
			onError: (error) => {
				toast.error(error.message || "Failed to reorder questions");
			},
		}),
	);

	// DnD sensors
	const sensors = useSensors(
		useSensor(PointerSensor, {
			activationConstraint: {
				distance: 5,
			},
		}),
		useSensor(KeyboardSensor, {
			coordinateGetter: sortableKeyboardCoordinates,
		}),
	);

	// Custom collision detection: pointerWithin for palette drops, closestCenter for canvas reordering
	const collisionDetection: CollisionDetection = (args) => {
		// If dragging from palette (has questionType), use pointerWithin for cross-container drops
		if (args.active.data.current?.questionType) {
			const pointerCollisions = pointerWithin(args);
			if (pointerCollisions.length > 0) {
				return pointerCollisions;
			}
		}
		// For canvas reordering, use closestCenter for better sortable behavior
		return closestCenter(args);
	};

	const handleDragStart = (event: DragStartEvent) => {
		const { active } = event;
		const data = active.data.current;

		if (data?.questionType) {
			// Dragging from palette
			setActiveDragItem({
				type: "palette",
				questionType: data.questionType as Question["type"],
			});
		} else {
			// Dragging existing question
			setActiveDragItem({
				type: "question",
				id: active.id as string,
			});
		}
	};

	const handleDragOver = (_event: DragOverEvent) => {
		// Just update visual state if needed, don't create questions
		// Question creation happens in handleDragEnd
	};

	const handleDragEnd = (event: DragEndEvent) => {
		const { active, over } = event;
		setActiveDragItem(null);

		if (!over) return;

		// Handle palette drop on canvas (create new question)
		if (active.data.current?.questionType && over.id === "canvas") {
			const questionType = active.data.current.questionType as Question["type"];
			createMutation.mutate({
				surveyId: survey.id,
				type: questionType,
				title: `New ${questionTypeLabels[questionType] || questionType}`,
				order: questions.length,
			});
			return;
		}

		// Handle reordering
		if (active.id !== over.id && over.id !== "canvas") {
			const oldIndex = questions.findIndex((q) => q.id === active.id);
			const newIndex = questions.findIndex((q) => q.id === over.id);

			if (oldIndex !== -1 && newIndex !== -1) {
				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
					(q, index) => ({
						...q,
						order: index,
					}),
				);

				setQuestions(newQuestions);

				reorderMutation.mutate({
					questions: newQuestions.map((q) => ({
						id: q.id,
						order: q.order,
					})),
				});
			}
		}
	};

	const contextValue: SurveyBuilderContextValue = {
		survey,
		questions,
		selectedQuestionId,
		setSelectedQuestionId,
		activeTab,
		setActiveTab,
		onQuestionsChange: setQuestions,
		paletteOpen,
		setPaletteOpen,
		propertiesOpen,
		setPropertiesOpen,
	};

	const safeQuestions = questions || [];

	// Custom drop animation that fades out smoothly
	const dropAnimation: typeof defaultDropAnimation = {
		...defaultDropAnimation,
		duration: 200,
		keyframes: ({ transform }) => [
			{ opacity: 1, transform: CSS.Transform.toString(transform.initial) },
			{
				opacity: 0,
				transform: CSS.Transform.toString({
					...transform.final,
					scale: 0.9,
				} as any),
			},
		],
	};

	// Render drag overlay
	const renderDragOverlay = () => {
		if (!activeDragItem) return null;

		if (activeDragItem.type === "palette") {
			const Icon =
				questionTypeIcons[activeDragItem.questionType] || ClipboardList;
			return (
				<Card className="border-2 border-violet-300 bg-white/95 shadow-xl backdrop-blur-sm">
					<CardContent className="flex items-center gap-3 p-4">
						<div className="rounded bg-violet-100 p-1.5">
							<Icon className="h-4 w-4 text-violet-600" />
						</div>
						<span className="font-medium">
							{questionTypeLabels[activeDragItem.questionType] ||
								activeDragItem.questionType}
						</span>
					</CardContent>
				</Card>
			);
		}

		// Dragging existing question
		const activeQuestion = safeQuestions.find(
			(q) => q.id === activeDragItem.id,
		);
		if (activeQuestion) {
			const Icon = questionTypeIcons[activeQuestion.type] || ClipboardList;
			return (
				<Card className="border-2 border-violet-300 bg-white/95 shadow-xl backdrop-blur-sm">
					<CardContent className="flex items-center gap-3 p-4">
						<div className="rounded bg-violet-100 p-1.5">
							<Icon className="h-4 w-4 text-violet-600" />
						</div>
						<span className="font-medium">{activeQuestion.title}</span>
					</CardContent>
				</Card>
			);
		}

		return null;
	};

	return (
		<SurveyBuilderContext.Provider value={contextValue}>
			<DndContext
				sensors={sensors}
				collisionDetection={collisionDetection}
				onDragStart={handleDragStart}
				onDragOver={handleDragOver}
				onDragEnd={handleDragEnd}
			>
				<div className={cn("flex h-full flex-col", className)}>
					<BuilderHeader
						leftActions={
							!isDesktop &&
							activeTab === "build" && (
								<div className="flex items-center gap-1">
									<Button
										variant="ghost"
										size="icon"
										onClick={() => setPaletteOpen(!paletteOpen)}
									>
										<PanelLeftClose className="h-4 w-4" />
									</Button>
								</div>
							)
						}
						rightActions={
							!isDesktop &&
							activeTab === "build" && (
								<div className="flex items-center gap-1">
									<Button
										variant="ghost"
										size="icon"
										onClick={() => setPropertiesOpen(!propertiesOpen)}
									>
										<PanelRightClose className="h-4 w-4" />
									</Button>
								</div>
							)
						}
					/>
					<div className="flex flex-1 overflow-hidden">
						{/* Left Palette - Responsive */}
						{activeTab === "build" && (
							<>
								{/* Desktop: Fixed sidebar */}
								{isDesktop && <QuestionPalette />}

								{/* Tablet/Mobile: Sheet overlay */}
								{!isDesktop && (
									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
										<SheetContent side="left" className="w-72 p-0">
											<QuestionPalette />
										</SheetContent>
									</Sheet>
								)}
							</>
						)}

						{/* Canvas */}
						<BuilderCanvas
							questions={questions}
							onQuestionsChange={setQuestions}
							activeDragItem={activeDragItem}
						/>

						{/* Right Properties Panel - Responsive */}
						{activeTab === "build" && (
							<>
								{/* Desktop: Fixed sidebar */}
								{isDesktop && <PropertiesPanel />}

								{/* Tablet/Mobile: Sheet overlay */}
								{!isDesktop && (
									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
										<SheetContent side="right" className="w-80 p-0">
											<PropertiesPanel />
										</SheetContent>
									</Sheet>
								)}
							</>
						)}
					</div>
				</div>

				<DragOverlay dropAnimation={dropAnimation}>
					{renderDragOverlay()}
				</DragOverlay>
			</DndContext>
		</SurveyBuilderContext.Provider>
	);
}

export { BuilderCanvas } from "./builder-canvas";
// Re-export sub-components for compound pattern
export { BuilderHeader } from "./builder-header";
export { PropertiesPanel } from "./properties-panel";
export { QuestionPalette } from "./question-palette";

# Improve Drag-and-Drop UX: Animations, Feedback & Consistency

## Context
The basic drag-and-drop functionality works (palette → canvas creates questions), but the UX is jarring:
1. **Visual disconnect**: Dropping from palette shows the item "pull back" to original position, then a new item appears suddenly
2. **No drop animation**: DragOverlay disappears instantly without transitioning to the drop location
3. **Inconsistent reordering**: `pointerWithin` collision detection doesn't work well for sortable items within canvas (needs `closestCenter`)
4. **Missing feedback**: No visual indication during drag-over about where the item will be placed

## Root Causes
1. **Single collision detection strategy**: Using `pointerWithin` for everything breaks sortable reordering which needs `closestCenter`
2. **No drop animation**: DragOverlay unmounts immediately without animating to final position
3. **No intermediate state**: No visual preview showing where the new question will appear
4. **Framer Motion layout conflict**: Layout animations can conflict with dnd-kit transforms

---

## Critical Files
- `apps/web/src/components/survey-builder/index.tsx` - DndContext, collision detection, DragOverlay
- `apps/web/src/components/survey-builder/builder-canvas.tsx` - Drop zone, visual feedback
- `apps/web/src/components/survey-builder/question-card.tsx` - Sortable item styling

---

## Implementation

### 1. Hybrid Collision Detection
**File: `index.tsx`**

Create a custom collision detection that uses different strategies based on drag source:

```tsx
import { pointerWithin, closestCenter, rectIntersection, CollisionDetection } from "@dnd-kit/core";

// Custom collision detection: pointerWithin for palette, closestCenter for canvas reordering
const collisionDetection: CollisionDetection = (args) => {
  // If dragging from palette (has questionType), use pointerWithin for cross-container
  if (args.active.data.current?.questionType) {
    const pointerCollisions = pointerWithin(args);
    if (pointerCollisions.length > 0) {
      return pointerCollisions;
    }
  }
  // For canvas reordering, use closestCenter for better sortable behavior
  return closestCenter(args);
};
```

Use in DndContext:
```tsx
<DndContext
  sensors={sensors}
  collisionDetection={collisionDetection}
  onDragStart={handleDragStart}
  onDragEnd={handleDragEnd}
>
```

### 2. Add Drop Animation with `dropAnimation`
**File: `index.tsx`**

Configure DragOverlay with proper drop animation:

```tsx
import { defaultDropAnimation, DragOverlay } from "@dnd-kit/core";

// Custom drop animation that fades out smoothly
const dropAnimation: typeof defaultDropAnimation = {
  ...defaultDropAnimation,
  duration: 200,
  keyframes: ({ transform }) => [
    { opacity: 1, transform: CSS.Transform.toString(transform.initial) },
    { opacity: 0, transform: CSS.Transform.toString({ ...transform.final, scale: 0.9 }) },
  ],
};

// In render:
<DragOverlay dropAnimation={dropAnimation}>
  {renderDragOverlay()}
</DragOverlay>
```

### 3. Add Visual Drop Zone Indicator
**File: `builder-canvas.tsx`**

When dragging a palette item over canvas, show a preview of where the new question will appear:

```tsx
// Add state for tracking drag-over
const { setNodeRef, isOver } = useDroppable({
  id: "canvas",
});

// In the questions list (not empty state), add a drop indicator:
{safeQuestions.length > 0 && isOver && activeDragItem?.type === "palette" && (
  <motion.div
    initial={{ opacity: 0, height: 0 }}
    animate={{ opacity: 1, height: "auto" }}
    exit={{ opacity: 0, height: 0 }}
    className="rounded-lg border-2 border-dashed border-violet-400 bg-violet-50 p-4 text-center"
  >
    <span className="text-violet-600 text-sm">Drop to add question here</span>
  </motion.div>
)}
```

**Required:** Pass `activeDragItem` from parent to BuilderCanvas via props or context.

### 4. Smooth Question Appearance Animation
**File: `builder-canvas.tsx`**

Enhance the new question appearance with spring animation:

```tsx
// In the questions.map():
<motion.div
  key={question.id}
  layout
  layoutId={`question-${question.id}`}
  initial={{ opacity: 0, y: 20, scale: 0.95 }}
  animate={{ opacity: 1, y: 0, scale: 1 }}
  exit={{ opacity: 0, scale: 0.95, transition: { duration: 0.15 } }}
  transition={{
    type: "spring",
    stiffness: 300,
    damping: 25,
    mass: 0.8
  }}
>
```

### 5. Fix Sortable Transform Conflict
**File: `question-card.tsx`**

Ensure the sortable transform doesn't conflict with Framer Motion:

```tsx
// Use CSS.Translate instead of CSS.Transform for smoother sorting
import { CSS } from "@dnd-kit/utilities";

const style = {
  transform: CSS.Translate.toString(transform), // Use Translate, not Transform
  transition,
  zIndex: isDragging ? 50 : undefined,
};

// Add layoutId for smooth layout animations
<motion.div layout layoutId={`card-${question.id}`}>
```

### 6. Enhanced Drag Overlay Styling
**File: `index.tsx`**

Make the drag overlay more visually distinct:

```tsx
// In renderDragOverlay for palette items:
<Card className="shadow-xl border-violet-300 border-2 bg-white/95 backdrop-blur-sm">
  <CardContent className="flex items-center gap-3 p-4">
    <div className="rounded bg-violet-100 p-1.5">
      <Icon className="h-4 w-4 text-violet-600" />
    </div>
    <span className="font-medium">{label}</span>
  </CardContent>
</Card>
```

---

## Implementation Order
1. Hybrid collision detection (fixes reordering)
2. Drop animation configuration (smooth fade-out)
3. Pass activeDragItem to BuilderCanvas (enables drop indicator)
4. Drop zone indicator (visual feedback during drag-over)
5. Enhanced question appearance animation
6. Fix sortable transform (smoother reordering)
7. Enhanced drag overlay styling

---

## Verification
- [ ] Drag "Short Text" from palette → canvas shows drop indicator
- [ ] Drop on canvas → DragOverlay fades out smoothly, new question animates in
- [ ] Drag to reorder questions → smooth sorting animation, no jitter
- [ ] Drop outside canvas → DragOverlay returns to origin smoothly
- [ ] Both empty canvas and populated canvas work correctly
- [ ] Mobile/tablet (with Sheet) still works

